    history: "টংগিবাড়ী এলাকার বৌদ্ধ নগর/স্তূপ ও প্রত্নস্থাপত্য নিয়ে গবেষণার জন্য পরিচিত স্থান। এই রেকর্ডের স্থানাঙ্ক আনুমানিক এবং কিছু ক্ষেত্রে উপজেলা/গ্রাম-কেন্দ্র নির্দেশ করে; এটিকে জরিপকৃত প্রবেশদ্বারের অবস্থান মনে করবেন না। সুনির্দিষ্ট প্রবেশপথ, বর্তমান কার্যক্রম, খোলার সময় ও দর্শনার্থী-নীতি স্থানীয়/সরকারি সূত্রে নিশ্চিত করুন।",
