    history: "রামুতে শিশু কল্যাণ/আবাসিক শিক্ষার কেন্দ্র হিসেবে একটি পুরোনো প্রকাশ্য বিবরণ পাওয়া যায়। তথ্যটি পুরোনো; বর্তমান কার্যক্রম, যোগাযোগ ও দর্শনার্থীর অনুমতি অবশ্যই সরাসরি নিশ্চিত করুন। এই রেকর্ডের স্থানাঙ্ক আনুমানিক এবং কিছু ক্ষেত্রে উপজেলা/গ্রাম-কেন্দ্র নির্দেশ করে; এটিকে জরিপকৃত প্রবেশদ্বারের অবস্থান মনে করবেন না। সুনির্দিষ্ট প্রবেশপথ, বর্তমান কার্যক্রম, খোলার সময় ও দর্শনার্থী-নীতি স্থানীয়/সরকারি সূত্রে নিশ্চিত করুন।",
    source: "https://jagatjyoti.wordpress.com/",
