    history: "লোকধর্ম বিষয়ক একটি প্রকাশ্য আলোচনায় দিনাজপুরের সতিমন ডাঙ্গি ও ধ্যানমগ্ন বুদ্ধসদৃশ প্রতিমাকে ঘিরে সত্যপীর/সত্যনারায়ণ ঐতিহ্যের সম্ভাব্য আন্তঃসম্পর্ককে গবেষণার বিষয় বলা হয়েছে। এটি নিশ্চিত বৌদ্ধ বিহার বলে প্রমাণিত নয়; স্থান ও প্রতিমার পরিচয় স্থানীয়/প্রত্নতাত্ত্বিক সূত্রে যাচাই করুন。 এটি একটি বিস্তৃত ঐতিহ্য-ডিরেক্টরিতে অন্তর্ভুক্ত করা হয়েছে। মানচিত্রের পিনটি আনুমানিক এবং কিছু ক্ষেত্রে গ্রাম/উপজেলা কেন্দ্র নির্দেশ করে—এটিকে জরিপকৃত প্রবেশদ্বার বা GPS নিশ্চিত স্থান হিসেবে ধরবেন না। সুনির্দিষ্ট ঠিকানা, নামের বানান, বর্তমান কার্যক্রম, দর্শনার্থীর নিয়ম এবং প্রবেশাধিকার স্থানীয় কর্তৃপক্ষ/প্রতিষ্ঠান ও সরকারি সূত্রে নিশ্চিত করুন।",
