    dhamma: "সক্রিয় ধর্মীয় ও সাংস্কৃতিক স্থান হলে স্থানীয় রীতি মানুন; অনুমতি ছাড়া ছবি তুলবেন না; প্রত্নবস্তু স্পর্শ বা স্থানান্তর করবেন না।",
