    history: "খাগড়াছড়ি সদর এলাকার পেরাছড়া অঞ্চলে বিহার, মহাশ্মশান ও সাধনাকেন্দ্রের উল্লেখ রয়েছে। এটি সক্রিয় ধর্মীয় স্থান; স্থানীয় রীতি জেনে যান。 এটি একটি বিস্তৃত ঐতিহ্য-ডিরেক্টরিতে অন্তর্ভুক্ত করা হয়েছে। মানচিত্রের পিনটি আনুমানিক এবং কিছু ক্ষেত্রে গ্রাম/উপজেলা কেন্দ্র নির্দেশ করে—এটিকে জরিপকৃত প্রবেশদ্বার বা GPS নিশ্চিত স্থান হিসেবে ধরবেন না। সুনির্দিষ্ট ঠিকানা, নামের বানান, বর্তমান কার্যক্রম, দর্শনার্থীর নিয়ম এবং প্রবেশাধিকার স্থানীয় কর্তৃপক্ষ/প্রতিষ্ঠান ও সরকারি সূত্রে নিশ্চিত করুন।",
    source: "https://www.khagrachhari.gov.bd/bn/site/page/1xX7-%E0%A6%AC%E0%A7%8C%E0%A6%A6%E0%A7%8D%E0%A6%A7-%E0%A6%AC%E0%A6%BF%E0%A6%B9%E0%A6%BE%E0%A6%B0",
