    history: "মহালছড়ির ক্যায়াংঘাট ইউনিয়নের বিহার তালিকায় ত্রিরত্নপুর/সারনাথ অরণ্য কুটিরের উল্লেখ রয়েছে। এটি একটি বিস্তৃত ঐতিহ্য-ডিরেক্টরিতে অন্তর্ভুক্ত করা হয়েছে। মানচিত্রের পিনটি আনুমানিক এবং কিছু ক্ষেত্রে গ্রাম/উপজেলা কেন্দ্র নির্দেশ করে—এটিকে জরিপকৃত প্রবেশদ্বার বা GPS নিশ্চিত স্থান হিসেবে ধরবেন না। সুনির্দিষ্ট ঠিকানা, নামের বানান, বর্তমান কার্যক্রম, দর্শনার্থীর নিয়ম এবং প্রবেশাধিকার স্থানীয় কর্তৃপক্ষ/প্রতিষ্ঠান ও সরকারি সূত্রে নিশ্চিত করুন।",
