    "history": "মহেশখালীর কালারমারছড়া ইউনিয়নের সরকারি তালিকায় নাম আছে; মানচিত্রের পিন স্থানীয়তা-ভিত্তিক আনুমানিক। মানচিত্রের পিনটি আনুমানিক ও স্থানীয়তা-ভিত্তিক; সুনির্দিষ্ট প্রবেশদ্বার/জিপিএস নয়। সরকারি বা স্থানীয় সূত্রে বর্তমান অবস্থা, দর্শনার্থীর নিয়ম, যাতায়াত ও প্রবেশাধিকার নিশ্চিত করুন।",
