    "dhamma": "সক্রিয় ধর্মীয় স্থানে স্থানীয় রীতি মানুন; অনুমতি ছাড়া ছবি তুলবেন না, ধর্মীয় অনুষ্ঠান ব্যাহত করবেন না এবং প্রত্নবস্তু স্পর্শ বা স্থানান্তর করবেন না।",
