    "history": "কক্সবাজার জেলা প্রশাসনের প্রকাশিত মন্দির/বিহার তালিকায় নাম রয়েছে। নাম ও স্থানীয়তা সরকারি তালিকা থেকে নেওয়া; এই রেকর্ডের GPS পিন আনুমানিক এবং সুনির্দিষ্ট প্রবেশদ্বার নয়। স্থানাঙ্কটি এলাকা-ভিত্তিক আনুমানিক নির্দেশক, নির্ভুল প্রবেশদ্বারের GPS নয়। যাওয়ার আগে সরকারি তালিকা, স্থানীয় বিহার কর্তৃপক্ষ ও Google Maps-এ সঠিক প্রবেশপথ, খোলার সময় এবং দর্শনার্থী-নীতি নিশ্চিত করুন।",
    "source": "https://coxsbazar.gov.bd/pages/static-pages/6991178035ce18e1c073db07",
