    dhamma: "প্রতিষ্ঠানের ধর্মীয়/সাংস্কৃতিক পরিচয় সম্পর্কে নিজস্ব বর্ণনা ও সংশ্লিষ্ট সম্প্রদায়ের বক্তব্য যাচাই করে উপস্থাপন করুন।",
    quoteRef: "https://baghc.edu.bd/",
