function selectedPlace() { return destinations.find(place => place.id === activePlaceId) || null; }
function selectPlace(id, panMap = true, refreshList = true) {
  const place = destinations.find(item => item.id === id);
  if (!place) return;
  activePlaceId = id;
  if (refreshList) {
    renderPlaces();
  } else {
    // Map-marker clicks must not destroy/rebuild markerLayer; otherwise the clicked popup can close instantly.
    document.querySelectorAll('[data-place-card]').forEach(card => {
      card.classList.toggle('is-selected', card.dataset.placeCard === id);
    });
  }
  renderPlaceDetail(place);
  const activeMap = window.__heritageLeafletMap || map;
  if (activeMap && panMap && Array.isArray(place.coords) && place.coords.length === 2 &&
      place.coords.every(Number.isFinite)) {
    activeMap.setView(place.coords, Math.max(activeMap.getZoom(), 10), {animate:false});
  }
  if (window.matchMedia('(max-width: 800px)').matches && panMap) {
    byId('placeDetail').scrollIntoView({ behavior: window.matchMedia('(prefers-reduced-motion: reduce)').matches ? 'auto' : 'smooth', block: 'nearest' });
  }
}
function telDigits(value) {
  return String(value || '').replace(/[^0-9+]/g, '');
}
function contactMarkup(place) {
  const person = (place.contactPerson || '').trim();
  const mobiles = String(place.mobile || '')
    .split(/[,;/|]+/)
    .map(item => item.trim())
    .filter(Boolean)
    .map(num => `<a href="tel:${escapeHtml(telDigits(num))}">${escapeHtml(num)}</a>`);
  if (!person && !mobiles.length) {
    return '<p class="detail-contact is-empty">☎ <strong>যোগাযোগ:</strong> এই প্রতিষ্ঠানের ভিক্ষুর নাম বা মোবাইল নম্বর সরকারি তালিকায় দেওয়া নেই, তাই কোনো নম্বর অনুমান করা হয়নি। স্থানীয় সংঘ বা বৌদ্ধ ধর্মীয় কল্যাণ ট্রাস্টের মাধ্যমে যাচাই করুন।</p>';
  }
  const parts = [];
  if (person) parts.push(`<strong>যোগাযোগ:</strong> ${escapeHtml(person)}`);
  if (mobiles.length) parts.push(`<strong>মোবাইল:</strong> ${mobiles.join(' · ')}`);
  return `<p class="detail-contact">☎ ${parts.join('<br>')}</p>`;
}
function renderPlaceDetail(place) {
  window.currentPlace = place;
  const media = mediaFor(place);
  const visited = visitedIds.has(place.id);
  const inTrip = itineraryIds.has(place.id);
  const wikiSearch = `https://bn.wikipedia.org/w/index.php?search=${encodeURIComponent(place.name)}`;
  const commonsSearch = `https://commons.wikimedia.org/w/index.php?search=${encodeURIComponent(place.name)}`;
  const archiveSearch = `https://archive.org/search?query=${encodeURIComponent(place.name + ' Bangladesh Buddhist')}`;
  const videoSearch = `https://www.youtube.com/results?search_query=${encodeURIComponent(place.name + ' Bangladesh')}`;
  const sourceUrl = place.source || (place.verificationPending
    ? googleSearch(`${place.name}, ${place.district}, Bangladesh`)
    : commonsSearch);
  const sourceDisplayLabel = place.source
    ? (place.sourceLabel || 'তথ্যসূত্র')
    : place.verificationPending
      ? 'নাম অনুসন্ধান (স্বাধীন উৎস যাচাই বাকি)'
      : (place.sourceLabel || 'সম্পর্কিত রেফারেন্স');
  const locationNote = !Array.isArray(place.coords)
    ? '<p class="map-pin-warning">📍 সুনির্দিষ্ট GPS যাচাই হয়নি—তাই ম্যাপে পিন দেখানো হয়নি। নাম ধরে Google Maps-এ খুঁজুন।</p>'
    : (place.pinApproximate || place.verificationPending)
      ? '<p class="map-pin-warning">⚠ এই মানচিত্রের পিন আনুমানিক; এটি জরিপকৃত প্রবেশদ্বারের GPS নয়। যাওয়ার আগে ঠিকানা স্থানীয়/সরকারি সূত্রে নিশ্চিত করুন।</p>'
      : '';
  const verificationNote = place.verificationPending
    ? '<p class="map-pin-warning">তথ্য-অবস্থা: যাচাই অপেক্ষমাণ। নির্ভরযোগ্য স্বাধীন উৎসে একই নাম/ঠিকানা নিশ্চিত না হওয়া পর্যন্ত এটিকে নিশ্চিত ঐতিহ্যস্থান হিসেবে ধরবেন না।</p>'
    : '';
  byId('placeDetail').innerHTML = `<div class="detail-empty-art" aria-hidden="true">${media ? `<img src="${media.image}" alt="" loading="lazy" referrerpolicy="no-referrer" onerror="this.style.display='none'" style="width:100%;height:100%;object-fit:cover;opacity:.72">` : ''}<span style="position:absolute;right:18px;top:4px">☸</span><i>🪷</i></div>
    <p class="section-kicker">SELECTED DESTINATION</p><h3>${escapeHtml(place.name)}</h3>
    <div class="detail-meta"><span class="detail-chip">${escapeHtml(place.district)} জেলা</span><span class="detail-chip">${escapeHtml(place.division)} বিভাগ</span><span class="detail-chip">${escapeHtml(place.category)}</span></div>${locationNote}${verificationNote}
    <p class="detail-history">${escapeHtml(place.history)}</p>
    ${contactMarkup(place)}
    <p><strong>🧭 যাওয়ার পরিকল্পনা:</strong> ${escapeHtml(place.trip)}</p>
    <p class="detail-quote">☸ <strong>শ্রদ্ধাশীল ভ্রমণ:</strong> ${escapeHtml(place.dhamma)} ${place.id === 'somapura' ? '<a href="https://whc.unesco.org/en/list/322/" target="_blank" rel="noopener noreferrer">[UNESCO]</a>' : ''}</p>
    <div class="detail-actions">
      <a class="action-primary" href="${mapLinkFor(place)}" target="_blank" rel="noopener noreferrer">↗ ${(place.pinApproximate || place.verificationPending || !Array.isArray(place.coords)) ? "Google Maps-এ স্থান খুঁজুন" : "Google Maps দিকনির্দেশ"}</a>
      <a href="${nearbyLink(place, 'ATM')}" target="_blank" rel="noopener noreferrer">▣ কাছাকাছি ATM</a>
      <a href="${nearbyLink(place, 'hotel and resort')}" target="_blank" rel="noopener noreferrer">⌂ হোটেল / রিসোর্ট</a>
      <a href="${videoSearch}" target="_blank" rel="noopener noreferrer">▷ YouTube ভিডিও</a>
      <a href="${wikiSearch}" target="_blank" rel="noopener noreferrer">W উইকিপিডিয়া</a>
      <a href="${commonsSearch}" target="_blank" rel="noopener noreferrer">▧ ছবি / Commons</a>
      <a href="${archiveSearch}" target="_blank" rel="noopener noreferrer">▤ আর্কাইভ / বই</a>
      <button type="button" data-action="visited" data-id="${place.id}">${visited ? '✓ দেখা হয়েছে' : '□ দেখা হয়েছে'}</button>
      <button type="button" data-action="itinerary" data-id="${place.id}">${inTrip ? '✓ তালিকায় আছে' : '+ তালিকায় যোগ'}</button>
    </div>
    <p class="detail-source">তথ্যসূত্র: <a href="${sourceUrl}" target="_blank" rel="noopener noreferrer">${escapeHtml(sourceDisplayLabel)} ↗</a>${media ? ` · <a href="${media.creditUrl}" target="_blank" rel="noopener noreferrer">ছবির কৃতিত্ব ↗</a>` : ''}</p>`;
  document.dispatchEvent(new CustomEvent('heritage-detail-rendered', { detail: { id: place.id } }));
}
function refreshHeritageMapLayout() {
  const container = byId('map');
  const activeMap = window.__heritageLeafletMap || map;
  if (!container || !activeMap) return;
  const rect = container.getBoundingClientRect();
  if (rect.width < 80 || rect.height < 120) return;
  try {
    activeMap.invalidateSize({pan:false, debounceMoveend:true});
    if (window.refreshHeritageMapTiles) window.refreshHeritageMapTiles();
    else if (window.__heritageTileLayer && typeof window.__heritageTileLayer.redraw === 'function') {
      window.__heritageTileLayer.redraw();
    }
  } catch (error) {
    console.warn('Map resize refresh deferred:', error);
  }
}
window.refreshHeritageMapLayout = refreshHeritageMapLayout;
function installMapResizeRecovery() {
  const container = byId('map');
  if (!container || container.dataset.resizeRecoveryInstalled === 'true') return;
  container.dataset.resizeRecoveryInstalled = 'true';
  const schedule = () => {
    if (window.__heritageMapResizeTimer) clearTimeout(window.__heritageMapResizeTimer);
    window.__heritageMapResizeTimer = setTimeout(refreshHeritageMapLayout, 90);
  };
  if (typeof ResizeObserver === 'function') {
    window.__heritageMapResizeObserver = new ResizeObserver(schedule);
    window.__heritageMapResizeObserver.observe(container);
  }
  window.addEventListener('resize', schedule, {passive:true});
  window.addEventListener('pageshow', schedule);
  document.addEventListener('visibilitychange', () => { if (!document.hidden) schedule(); });
  [120, 500, 1100, 1800].forEach(delay => setTimeout(refreshHeritageMapLayout, delay));
}
function attachHeritageTileLayer(activeMap) {
  if (!activeMap || typeof L === 'undefined') return null;
  const providers = [
    {name:'OpenStreetMap',url:'https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',
      options:{subdomains:['a','b','c'],maxZoom:19,keepBuffer:3,updateWhenIdle:true,updateWhenZooming:false,
        attribution:'&copy; <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener noreferrer">OpenStreetMap</a>'}},
    {name:'CARTO',url:'https://{s}.basemaps.cartocdn.com/light_all/{z}/{x}/{y}{r}.png',
      options:{subdomains:'abcd',maxZoom:20,keepBuffer:3,updateWhenIdle:true,updateWhenZooming:false,
        attribution:'&copy; OpenStreetMap contributors &copy; <a href="https://carto.com/attributions" target="_blank" rel="noopener noreferrer">CARTO</a>'}},
    {name:'Esri World Street Map',url:'https://server.arcgisonline.com/ArcGIS/rest/services/World_Street_Map/MapServer/tile/{z}/{y}/{x}',
      options:{maxZoom:19,keepBuffer:3,updateWhenIdle:true,updateWhenZooming:false,
        attribution:'Tiles &copy; <a href="https://www.esri.com/" target="_blank" rel="noopener noreferrer">Esri</a>'}}
  ];
  let providerIndex=0, timer=null, layer=null;
  const statusNode=()=>byId('mapActionStatus');
  const setStatus=message=>{
    const node=statusNode();
    if(node && (!node.dataset.context || node.dataset.context==='tiles')){
      node.dataset.context='tiles';node.textContent=message;
    }
  };
  const mount=()=>{
    if(timer)clearTimeout(timer);
    if(layer){try{activeMap.removeLayer(layer)}catch(_){}}
    const provider=providers[providerIndex];
    let loaded=0,errors=0,switched=false;
    const failover=()=>{
      if(switched||providerIndex>=providers.length-1)return;
      switched=true;providerIndex++;
      setStatus('ম্যাপের টাইল অসম্পূর্ণ এসেছে; বিকল্প ম্যাপ সার্ভার চালু হচ্ছে…');
      mount();
    };
    layer=L.tileLayer(provider.url,provider.options);
    window.__heritageTileLayer=layer;
    layer.on('tileload',()=>{
      loaded++;
      if(loaded>=3&&providerIndex>0)setStatus('বিকল্প ম্যাপ চালু হয়েছে ('+provider.name+')।');
      else if(loaded>=4&&providerIndex===0&&statusNode()?.dataset.context==='tiles'){
        statusNode().textContent='';delete statusNode().dataset.context;
      }
    });
    layer.on('tileerror',()=>{errors++;if(errors>=3&&loaded<4)failover();});
    layer.addTo(activeMap);
    timer=setTimeout(()=>{
      if(loaded<4&&providerIndex<providers.length-1)failover();
      else if(loaded===0){
        setStatus('ম্যাপ সার্ভার থেকে টাইল আসছে না। নেটওয়ার্ক/ট্র্যাকার ব্লকার পরীক্ষা করুন; নিচের সেবা ও স্থান অনুসন্ধান ব্যবহার করা যাবে।');
      }
    },7000);
    return layer;
  };
  window.refreshHeritageMapTiles=()=>{
    try{activeMap.invalidateSize({pan:false,debounceMoveend:true});if(window.__heritageTileLayer)window.__heritageTileLayer.redraw()}catch(_){}
  };
  window.__heritageTileProviderReset=()=>{providerIndex=0;mount()};
  mount();
  return layer;
}
window.attachHeritageTileLayer=attachHeritageTileLayer;

function initMap() {
  const container = byId('map');
  if (typeof L === 'undefined') {
    container.innerHTML = '<div class="map-loading">ম্যাপ লাইব্রেরি লোড হয়নি। নিচের Google Maps লিংক দিয়ে স্থান ও রুট দেখুন।</div>';
    return;
  }
  // Clear the static loading overlay before Leaflet creates its map panes.
  container.innerHTML = '';
  map = L.map('map', { scrollWheelZoom: false, preferCanvas: true }).setView([23.685, 90.3563], 7);
  window.__heritageLeafletMap = map;
  attachHeritageTileLayer(map);
  installMapResizeRecovery();
  markerLayer = typeof L.markerClusterGroup === 'function'
    ? L.markerClusterGroup({
        chunkedLoading: true,
        chunkInterval: 200,
        chunkDelay: 35,
        maxClusterRadius: 42,
        spiderfyOnMaxZoom: true,
        showCoverageOnHover: false,
        disableClusteringAtZoom: 13,
        iconCreateFunction: cluster => L.divIcon({
          className: '',
          html: '<div class="custom-cluster-icon"><span>☸</span><b>' + cluster.getChildCount() + '</b></div>',
          iconSize: [42, 42],
          iconAnchor: [21, 21]
        })
      })
    : L.layerGroup();
  markerLayer.addTo(map);
  window.__heritageMarkerLayer = markerLayer;
  map.whenReady(() => {
    setTimeout(() => map?.invalidateSize(), 120);
    setTimeout(() => map?.invalidateSize(), 650);
  });
  // renderPlaces applies the current search/filters to the map after map creation.
  renderPlaces();
}
function updateMarkers(list) {
  const activeMap = window.__heritageLeafletMap || map;
  const activeLayer = window.__heritageMarkerLayer || markerLayer;
  if (!activeMap || !activeLayer || typeof L === 'undefined') return;
  const pins = list.filter(place => Array.isArray(place.coords) && place.coords.length === 2 &&
    place.coords.every(Number.isFinite)).map(place => {
    let marker = markerCache.get(place.id);
    if (!marker) {
      const icon = L.divIcon({
        className: '',
        html: '<div class="custom-map-pin" aria-hidden="true"><span>☸</span></div>',
        iconSize: [34, 34],
        iconAnchor: [17, 17],
        popupAnchor: [0, -18]
      });
      marker = L.marker(place.coords, {icon, title:place.name, alt:place.name});
      marker.bindPopup('<strong>' + escapeHtml(place.name) + '</strong><br>' +
        escapeHtml(place.district || '') + ', ' + escapeHtml(place.division || '') +
        ((place.pinApproximate || place.verificationPending) ? '<br><em>পিন আনুমানিক / যাচাইাধীন</em>' : '') +
        '<br><a href="' + mapLinkFor(place) + '" target="_blank" rel="noopener noreferrer">Google Maps-এ স্থান / রুট খুঁজুন ↗</a>');
      marker.on('click', () => selectPlace(place.id, false, false));
      markerCache.set(place.id, marker);
    }
    return marker;
  });
  activeLayer.clearLayers();
  if (typeof activeLayer.addLayers === 'function') activeLayer.addLayers(pins);
  else pins.forEach(marker => activeLayer.addLayer(marker));
  if (userPosition) addUserMarker(userPosition.lat, userPosition.lng);
}
function addUserMarker(lat, lng) {
  const activeMap = window.__heritageLeafletMap || map;
  if (!activeMap || typeof L === 'undefined') return;
  userPosition = {lat, lng};
  const previous = window.__heritageUserLocationMarker || userMarker;
  if (previous) { try { previous.remove(); } catch (_) {} }
  const icon = L.divIcon({className:'', html:'<div class="user-map-pin"></div>', iconSize:[18,18], iconAnchor:[9,9]});
  userMarker = L.marker([lat,lng], {icon}).addTo(activeMap).bindPopup('আপনার বর্তমান অবস্থান');
  window.__heritageUserLocationMarker = userMarker;
}
function requestLocation(onSuccess, onFailure) {
  const status = byId('mapActionStatus');
  const report = (message, kind='info') => {
    if (status) { status.textContent = message; status.dataset.kind = kind; status.dataset.context = 'location'; }
  };
  if (!navigator.geolocation) {
    const reason = 'এই ব্রাউজারে অবস্থান শনাক্ত করার সুবিধা নেই।';
    report(reason,'error');
    if (typeof onFailure === 'function') onFailure(reason); else alert(reason);
    return;
  }
  if (!window.isSecureContext) {
    const reason = 'অবস্থান জানার জন্য HTTPS ঠিকানা খুলুন; GitHub Pages-এর secure URL ব্যবহার করুন।';
    report(reason,'error');
    if (typeof onFailure === 'function') onFailure(reason); else alert(reason);
    return;
  }
  const button = byId('locateMe');
  if (button) { button.disabled = true; button.textContent = 'অবস্থান খোঁজা হচ্ছে…'; }
  report('আপনার ডিভাইসের অবস্থানের অনুমতি চাওয়া হয়েছে…');
  navigator.geolocation.getCurrentPosition(position => {
    const lat = position.coords.latitude, lng = position.coords.longitude;
    addUserMarker(lat,lng);
    const activeMap = window.__heritageLeafletMap || map;
    if (activeMap) {
      activeMap.setView([lat,lng],12,{animate:false});
      if (window.refreshHeritageMapTiles) window.refreshHeritageMapTiles();
    }
    report('আপনার অবস্থান পাওয়া গেছে (' + lat.toFixed(5) + ', ' + lng.toFixed(5) + ')। ম্যাপের টাইল রিফ্রেশ করা হচ্ছে।','success');
    if (button) { button.disabled = false; button.textContent = '◎ আমার অবস্থান'; }
    if (typeof onSuccess === 'function') onSuccess(lat,lng);
  }, error => {
    if (button) { button.disabled = false; button.textContent = '◎ আমার অবস্থান'; }
    const reason = error.code === 1
      ? 'অবস্থান অনুমতি বন্ধ আছে। ব্রাউজারের Site settings → Location → Allow করে আবার চাপুন।'
      : error.code === 3 ? 'অবস্থান পাওয়ার সময় শেষ হয়েছে। GPS/Location চালু করে আবার চেষ্টা করুন।'
      : 'ডিভাইসের অবস্থান পাওয়া যায়নি। GPS/Location চালু আছে কি না দেখুন।';
    report(reason,'error');
    if (typeof onFailure === 'function') onFailure(reason); else alert(reason);
  }, {enableHighAccuracy:false, timeout:15000, maximumAge:60000});
}
function toggleVisited(id) {
  if (visitedIds.has(id)) visitedIds.delete(id); else visitedIds.add(id);
  saveStorage('buddhistHeritageVisited', [...visitedIds]);
  renderPlaces(); renderItinerary();
  const place = destinations.find(item => item.id === id);
  if (place && activePlaceId === id) renderPlaceDetail(place);
}
function toggleItinerary(id) {
  if (itineraryIds.has(id)) itineraryIds.delete(id); else itineraryIds.add(id);
  saveStorage('buddhistHeritageItinerary', [...itineraryIds]);
  renderPlaces(); renderItinerary();
  const place = destinations.find(item => item.id === id);
  if (place && activePlaceId === id) renderPlaceDetail(place);
}
function updateProgress() {
  byId('visitedCount').textContent = bnDigits(visitedIds.size);
  byId('itineraryCount').textContent = bnDigits(itineraryIds.size);
  byId('visitedStat').textContent = bnDigits(visitedIds.size);
  const percent = Math.round((visitedIds.size / destinations.length) * 100);
  byId('progressPercent').textContent = `${bnDigits(percent)}%`;
}
function renderItinerary() {
  const places = destinations.filter(place => itineraryIds.has(place.id));
  if (!places.length) {
    byId('itineraryList').innerHTML = '<p class="itinerary-empty">তালিকা এখনো খালি। কোনো স্থানের কার্ড থেকে “তালিকায় যোগ” চাপুন।</p>';
  } else {
    byId('itineraryList').innerHTML = places.map(place => `<div class="itinerary-item"><input class="itinerary-check" type="checkbox" aria-label="${escapeHtml(place.name)} দেখা হয়েছে" data-action="visited" data-id="${place.id}" ${visitedIds.has(place.id) ? 'checked' : ''}><div><strong>${escapeHtml(place.name)}</strong><small>${escapeHtml(place.district)} · ${escapeHtml(place.division)} বিভাগ</small></div><button class="itinerary-remove" type="button" data-action="remove-itinerary" data-id="${place.id}" aria-label="${escapeHtml(place.name)} তালিকা থেকে সরান">×</button></div>`).join('');
  }
  updateProgress();
}
function exportItinerary() {
  const selected = destinations.filter(place => itineraryIds.has(place.id));
  if (!selected.length) { alert('ডাউনলোডের আগে অন্তত একটি স্থান ভ্রমণ তালিকায় যোগ করুন।'); return; }
  const lines = [
    'বাংলাদেশের বৌদ্ধ ঐতিহ্যবাহী স্থান নির্দেশিকা',
    `তালিকা তৈরি: ${new Date().toLocaleDateString('bn-BD')}`,
    '',
    ...selected.map((place, index) => `${index + 1}. ${place.name}\n   জেলা: ${place.district}; বিভাগ: ${place.division}\n   Google Maps: ${mapLinkFor(place)}\n   ATM: ${nearbyLink(place, 'ATM')}\n   হোটেল/রিসোর্ট: ${nearbyLink(place, 'hotel and resort')}\n   তথ্যসূত্র: ${place.source}`)
  ];
  const blob = new Blob(['\ufeff' + lines.join('\n\n')], { type: 'text/plain;charset=utf-8' });
  const url = URL.createObjectURL(blob);
  const anchor = document.createElement('a'); anchor.href = url; anchor.download = 'buddhist-heritage-bangladesh-itinerary.txt';
  document.body.appendChild(anchor); anchor.click(); anchor.remove(); URL.revokeObjectURL(url);
}

byId('placeGrid').addEventListener('click', event => {
  const button = event.target.closest('[data-action]');
  if (button) {
    const id = button.dataset.id;
    if (button.dataset.action === 'details') selectPlace(id);
    if (button.dataset.action === 'visited') toggleVisited(id);
    if (button.dataset.action === 'itinerary') toggleItinerary(id);
    return;
  }
  const card = event.target.closest('[data-place-card]');
  if (card) selectPlace(card.dataset.placeCard);
});
byId('placeDetail').addEventListener('click', event => {
  const target = event.target.closest('[data-action]');
  if (!target) return;
  if (target.dataset.action === 'visited') toggleVisited(target.dataset.id);
  if (target.dataset.action === 'itinerary') toggleItinerary(target.dataset.id);
});
byId('itineraryList').addEventListener('change', event => {
  if (event.target.matches('input[data-action="visited"]')) toggleVisited(event.target.dataset.id);
});
byId('itineraryList').addEventListener('click', event => {
  const button = event.target.closest('[data-action="remove-itinerary"]');
  if (button) { itineraryIds.delete(button.dataset.id); saveStorage('buddhistHeritageItinerary', [...itineraryIds]); renderPlaces(); renderItinerary(); }
});
let placeSearchTimer = null;
['placeSearch', 'divisionFilter', 'districtFilter', 'upazilaFilter', 'thanaFilter', 'unionFilter', 'categoryFilter'].forEach(id => {
  const control = byId(id);
  if (control) control.addEventListener(id === 'placeSearch' ? 'input' : 'change', () => {
    if (id === 'placeSearch') {
      clearTimeout(placeSearchTimer);
      placeSearchTimer = setTimeout(renderPlaces, 140);
    } else renderPlaces();
  });
});
byId('clearFilters').addEventListener('click', () => {
  byId('placeSearch').value = '';
  ['divisionFilter', 'districtFilter', 'upazilaFilter', 'thanaFilter', 'unionFilter', 'categoryFilter'].forEach(id => {
    const control = byId(id);
    if (control) control.value = 'all';
  });
  byId('divisionFilter')?.dispatchEvent(new Event('change', { bubbles: true }));
  renderPlaces();
});
byId('loadMorePlaces')?.addEventListener('click', () => {
  visiblePlaceLimit += placePageSize;
  renderPlaces(true);
});
byId('sortVisited').addEventListener('click', () => { sortUnvisitedFirst = !sortUnvisitedFirst; byId('sortVisited').textContent = sortUnvisitedFirst ? 'দেখা হয়নি আগে ↑' : 'নাম অনুসারে A–Z'; renderPlaces(); });
byId('refreshMap')?.addEventListener('click',()=>{
  const activeMap=window.__heritageLeafletMap||map;
  if(!activeMap){alert('ম্যাপ লাইব্রেরি লোড হয়নি। পৃষ্ঠা reload করে আবার চেষ্টা করুন।');return;}
  if(window.__heritageTileProviderReset)window.__heritageTileProviderReset();
  if(window.refreshHeritageMapTiles)window.refreshHeritageMapTiles();
  if(window.refreshHeritageMapLayout)window.refreshHeritageMapLayout();
  const status=byId('mapActionStatus');
  if(status){status.textContent='ম্যাপ রিফ্রেশ হচ্ছে…';status.dataset.context='tiles';}
});
byId('locateMe').addEventListener('click', () => requestLocation());
const mapServiceQueries = {
  medical:'emergency hospital emergency department clinic',
  pharmacy:'pharmacy drug store',
  hotel:'hotel guest house',
  transport:'bus ticket counter train ticket counter launch ticket counter transport terminal',
  police:'police station',
  fire:'fire service fire station'
};
function placeQueryForService(place){return [place.name,place.upazila,place.district,'Bangladesh'].filter(Boolean).join(', ');}
function openMapServiceSearch(kind){
  const query=mapServiceQueries[kind];if(!query)return;
  const status=byId('mapActionStatus');
  const report=message=>{if(status){status.textContent=message;status.dataset.context='services';status.dataset.kind='info';}};
  const makeUrl=target=>googleSearch(query+' near '+target);
  const open=url=>{const tab=window.open(url,'_blank');if(tab){try{tab.opener=null;}catch(_){}}else if(status){status.innerHTML='নতুন ট্যাব ব্লক হয়েছে। <a href="'+escapeHtml(url)+'" target="_blank" rel="noopener noreferrer">Google Maps খুলুন ↗</a>';status.dataset.context='services';status.dataset.kind='info';}};
  if(userPosition){open(makeUrl(userPosition.lat+','+userPosition.lng));report('আপনার বর্তমান অবস্থানের কাছে সেবা অনুসন্ধান খোলা হয়েছে।');return;}
  const place=selectedPlace();
  if(place){open(makeUrl(placeQueryForService(place)));report('নির্বাচিত স্থানকে কেন্দ্র করে সেবা অনুসন্ধান খোলা হয়েছে।');return;}
  // Keep a reference to the blank tab while waiting for the GPS permission response.
  const tab=window.open('about:blank','_blank');
  if(tab)tab.opener=null;
  const fallback=()=>{const url=googleSearch(query+' Bangladesh');if(tab&&!tab.closed)tab.location.href=url;else open(url);};
  if(!navigator.geolocation||!window.isSecureContext){fallback();report('কাছাকাছি ফলাফলের জন্য Location Allow করুন; আপাতত বাংলাদেশের সাধারণ অনুসন্ধান খোলা হয়েছে।');return;}
  report('আপনার অবস্থান নিয়ে কাছাকাছি সেবা খোঁজা হচ্ছে…');
  navigator.geolocation.getCurrentPosition(pos=>{
    userPosition={lat:pos.coords.latitude,lng:pos.coords.longitude};
    const url=makeUrl(userPosition.lat+','+userPosition.lng);
    if(tab&&!tab.closed)tab.location.href=url;else open(url);
    report('আপনার অবস্থানের কাছে সেবা খোঁজা হয়েছে। Google Maps-এ দূরত্ব ও সময় যাচাই করুন।');
  },()=>{
    fallback();report('অবস্থান পাওয়া যায়নি; বাংলাদেশের সাধারণ অনুসন্ধান খোলা হয়েছে। Location permission চালু করে আবার চেষ্টা করুন।');
  },{enableHighAccuracy:false,timeout:12000,maximumAge:60000});
}
document.querySelectorAll('[data-map-service]').forEach(button=>button.addEventListener('click',()=>openMapServiceSearch(button.dataset.mapService)));
byId('nearbyAtm').addEventListener('click', () => {
  if (userPosition) { window.open(googleSearch(`ATM near ${userPosition.lat},${userPosition.lng}`), '_blank', 'noopener,noreferrer'); return; }
  // Open a blank tab synchronously to avoid popup blockers after geolocation resolves.
  const resultTab = window.open('about:blank', '_blank');
  if (resultTab) {
    resultTab.document.title = 'ATM খোঁজা হচ্ছে';
    resultTab.document.body.innerHTML = '<p style="font:16px sans-serif;padding:24px">আপনার অবস্থান শনাক্ত করা হচ্ছে…</p>';
  }
  requestLocation((lat, lng) => {
    const url = googleSearch(`ATM near ${lat},${lng}`);
    if (resultTab && !resultTab.closed) resultTab.location.href = url;
    else { byId('nearbyAtm').textContent = 'ATM-এর জন্য আবার চাপুন ↗'; }
  }, reason => {
    if (resultTab && !resultTab.closed) resultTab.close();
    alert(`${reason} আগে “আমার অবস্থান” চালু করুন বা কোনো গন্তব্য নির্বাচন করে তার ATM লিংক ব্যবহার করুন।`);
  });
});
byId('exportItinerary').addEventListener('click', exportItinerary);
byId('clearItinerary').addEventListener('click', () => {
  if (!itineraryIds.size) return;
  if (confirm('ভ্রমণ তালিকার সব স্থান মুছে ফেলবেন?')) { itineraryIds.clear(); saveStorage('buddhistHeritageItinerary', []); renderPlaces(); renderItinerary(); }
});
byId('navToggle').addEventListener('click', () => {
  const isOpen = byId('siteNav').classList.toggle('is-open');
  byId('navToggle').setAttribute('aria-expanded', String(isOpen));
});
byId('siteNav').addEventListener('click', event => {
  if (event.target.closest('a')) { byId('siteNav').classList.remove('is-open'); byId('navToggle').setAttribute('aria-expanded', 'false'); }
});


/* Community travel reviews: device-local submissions plus records published in content.json. */
function reviewDateLabel(value) {
  if (!value) return 'তারিখ উল্লেখ নেই';
  const part = String(value).split('T')[0];
  const date = new Date(part + 'T12:00:00');
  return Number.isNaN(date.getTime()) ? escapeHtml(part) : date.toLocaleDateString('bn-BD');
}
function normalizePublicReview(post) {
  return {
    id: String(post.id || post.title || 'review'),
    placeId: String(post.placeId || ''),
    placeName: String(post.placeName || post.title || 'স্থান উল্লেখ নেই'),
    rating: Math.max(0, Math.min(5, Number(post.rating) || 0)),
    author: String(post.author || post.credit || 'কমিউনিটি সদস্য'),
    visitDate: String(post.visitDate || ''),
    text: String(post.text || post.body || post.summary || ''),
    createdAt: String(post.createdAt || ''),
    sourceUrl: String(post.sourceUrl || ''),
    isPublic: true
  };
}
function localTravelReviews() {
  return readStorage('buddhistHeritageTravelReviews', []).filter(item => item && item.type === 'review');
}
function renderReviewPlaceOptions() {
  const select = byId('reviewPlaceSelect');
  if (!select) return;
  const current = select.value;
  select.innerHTML = '<option value="">স্থান নির্বাচন করুন…</option>' + destinations.slice()
    .sort((a,b) => a.name.localeCompare(b.name, 'bn'))
    .map(place => '<option value="' + escapeHtml(place.id) + '">' + escapeHtml(place.name) + ' — ' + escapeHtml(place.district) + '</option>')
    .join('');
  if (destinations.some(place => place.id === current)) select.value = current;
}
function renderReviews() {
  if (!byId('reviewList')) return;
  renderReviewPlaceOptions();
  const local = localTravelReviews().map(item => Object.assign({}, normalizePublicReview(item), {
    author: String(item.author || 'অতিথি'), isPublic: false
  }));
  const published = publishedReviewRecords.map(normalizePublicReview);
  const seen = new Set();
  const reviews = published.concat(local).filter(item => {
    const key = item.id + '|' + item.placeName + '|' + item.createdAt;
    if (seen.has(key)) return false;
    seen.add(key); return true;
  }).sort((a,b) => String(b.createdAt || b.visitDate || '').localeCompare(String(a.createdAt || a.visitDate || '')));
  byId('reviewCount').textContent = bnDigits(reviews.length);
  if (!reviews.length) {
    byId('reviewList').innerHTML = '<p class="review-empty">এখনো কোনো রিভিউ নেই। আপনি প্রথমে একটি স্থান বেছে অভিজ্ঞতা যোগ করতে পারেন।</p>';
    return;
  }
  byId('reviewList').innerHTML = reviews.map(review => {
    const rating = Math.max(0, Math.min(5, Number(review.rating) || 0));
    const place = destinations.find(item => item.id === review.placeId);
    const starLine = rating ? '★'.repeat(rating) + '☆'.repeat(5-rating) + '<small>' + bnDigits(rating) + '/৫</small>' : 'রেটিং নেই';
    const sourceLink = review.sourceUrl ? '<p class="review-card-source"><a href="' + escapeHtml(review.sourceUrl) + '" target="_blank" rel="noopener noreferrer">তথ্যসূত্র ↗</a></p>' : '';
    return '<article class="review-card">' +
      '<div class="review-card-top"><div><h4>' + escapeHtml(review.placeName) + '</h4><p>' + escapeHtml(place ? place.district + ' জেলা' : 'বাংলাদেশ') + '</p></div>' +
      '<span class="review-visibility ' + (review.isPublic ? 'is-public' : 'is-local') + '">' + (review.isPublic ? 'প্রকাশিত' : 'এই ডিভাইসে') + '</span></div>' +
      '<div class="review-stars" aria-label="' + (rating ? bnDigits(rating) + ' / ৫' : 'রেটিং উল্লেখ নেই') + '">' + starLine + '</div>' +
      '<p class="review-card-text">' + escapeHtml(review.text) + '</p>' +
      '<div class="review-card-footer"><span>✎ ' + escapeHtml(review.author || 'অতিথি') + '</span><span>ভ্রমণ: ' + escapeHtml(reviewDateLabel(review.visitDate)) + '</span></div>' +
      sourceLink + '</article>';
  }).join('');
}
function downloadReviewBackup() {
  const reviews = localTravelReviews();
  if (!reviews.length) { alert('ডাউনলোড করার মতো আপনার কোনো লোকাল রিভিউ নেই।'); return; }
  const payload = reviews.map(review => Object.assign({}, review, {
    type:'review', title:review.placeName || review.title,
    summary:review.text || review.summary || '', body:review.text || review.body || '',
    credit:review.author || review.credit || 'অতিথি'
  }));
  const blob = new Blob(['\ufeff' + JSON.stringify(payload, null, 2)], {type:'application/json;charset=utf-8'});
  const url = URL.createObjectURL(blob);
  const anchor = document.createElement('a');
  anchor.href = url; anchor.download = 'buddhist-heritage-travel-reviews.json';
  document.body.appendChild(anchor); anchor.click(); anchor.remove(); URL.revokeObjectURL(url);
}
byId('reviewForm')?.addEventListener('submit', event => {
  event.preventDefault();
  const place = destinations.find(item => item.id === byId('reviewPlaceSelect').value);
  const rating = Number(byId('reviewRating').value);
  const textValue = byId('reviewText').value.trim();
  if (!place || !rating || textValue.length < 10) {
    byId('reviewStatus').textContent = 'স্থান, রেটিং ও অন্তত ১০ অক্ষরের অভিজ্ঞতা লিখুন.';
    byId('reviewStatus').dataset.kind = 'error';
    return;
  }
  const author = byId('reviewAuthor').value.trim() || 'অতিথি';
  const review = {
    id:'review-' + Date.now() + '-' + Math.random().toString(36).slice(2,8),
    type:'review', placeId:place.id, placeName:place.name, title:place.name,
    district:place.district, division:place.division, rating:rating,
    visitDate:byId('reviewVisitDate').value, author:author, credit:author,
    summary:textValue, body:textValue, text:textValue, createdAt:new Date().toISOString()
  };
  const records = localTravelReviews();
  records.unshift(review);
  saveStorage('buddhistHeritageTravelReviews', records);
  byId('reviewForm').reset();
  renderReviews();
  byId('reviewStatus').textContent = 'রিভিউ এই ব্রাউজারে সেভ হয়েছে। অন্য দর্শকদের জন্য প্রকাশ করতে JSON ডাউনলোড করে যাচাইসহ প্রকাশিত content.json-এ যোগ করুন।';
  byId('reviewStatus').dataset.kind = 'success';
});
byId('exportReviews')?.addEventListener('click', downloadReviewBackup);
byId('clearLocalReviews')?.addEventListener('click', () => {
  if (!localTravelReviews().length) { alert('এই ডিভাইসে মোছার মতো রিভিউ নেই।'); return; }
  if (confirm('এই ব্রাউজারে সেভ করা আপনার সব রিভিউ মুছবেন? প্রকাশিত রিভিউ মুছবে না।')) {
    saveStorage('buddhistHeritageTravelReviews', []);
    renderReviews();
    byId('reviewStatus').textContent = 'এই ব্রাউজারের লোকাল রিভিউ মুছে ফেলা হয়েছে।';
    byId('reviewStatus').dataset.kind = 'success';
  }
});

async function loadPublishedCommunityPlaces() {
  try {
    const response = await fetch(new URL('./content.json', document.baseURI), { cache: 'no-store' });
    if (!response.ok) return;
    const loaded = await response.json();
    const posts = Array.isArray(loaded) ? loaded : Array.isArray(loaded.posts) ? loaded.posts : [];
    publishedReviewRecords = posts.filter(post => post && post.type === 'review');
    posts.filter(post => post && post.type === 'place').forEach(post => {
      const latitude = Number(post.latitude);
      const longitude = Number(post.longitude);
      if (!post.title || post.latitude === null || post.latitude === undefined || post.latitude === '' || post.longitude === null || post.longitude === undefined || post.longitude === '' || !Number.isFinite(latitude) || !Number.isFinite(longitude) || latitude < -90 || latitude > 90 || longitude < -180 || longitude > 180) return;
      const id = `community-post-${String(post.id || post.title).replace(/[^a-zA-Z0-9_-]/g, '-').slice(0, 80)}`;
      if (destinations.some(place => place.id === id)) return;
      const imageIsImage = String(post.mediaType || '').startsWith('image/') || /\.(png|jpe?g|gif|webp|avif|svg)(\?|$)/i.test(String(post.mediaPath || post.mediaUrl || ''));
      destinations.push({
        id,
        name: String(post.title).slice(0, 140),
        district: String(post.district || 'জেলা উল্লেখ নেই').slice(0, 60),
        division: String(post.division || ''),
        kind: 'কমিউনিটি স্থান',
        category: 'কমিউনিটি স্থান',
        coords: [latitude, longitude],
        imageKey: null,
        customImageUrl: imageIsImage ? (post.mediaPath || post.mediaUrl || '') : '',
        summary: String(post.summary || '').slice(0, 500),
        history: String(post.body || post.summary || 'এই স্থানটি কমিউনিটি সদস্যের দেওয়া তথ্য থেকে যুক্ত হয়েছে। ভ্রমণের আগে স্থানীয়/বিশ্বস্ত সূত্রে যাচাই করুন।').slice(0, 10000),
        source: post.sourceUrl || '',
        sourceLabel: post.credit || 'কমিউনিটি-যোগ করা স্থান',
        dhamma: 'কমিউনিটি-যোগ করা তথ্য; যাত্রার আগে অবস্থান, প্রবেশাধিকার ও সূত্র যাচাই করুন।',
        quoteRef: post.sourceUrl || 'https://suttacentral.net/',
        trip: 'গন্তব্যে যাওয়ার আগে Google Maps-এ রুট ও স্থানীয় প্রবেশের নিয়ম যাচাই করুন.'
      });
    });
  } catch (error) {
    // A missing content.json is expected for a fresh local preview or a file:// launch.
  }
}

window.__heritageCoreScriptReady = true;
byId('currentYear').textContent = new Date().getFullYear();
/* Initialize the map before optional panels. A review/storage error must never leave the map overlay stuck. */
try {
  initMap();
} catch (error) {
  console.error('Heritage map initialization failed:', error);
  const mapContainer = byId('map');
  // Do not destroy Leaflet's panes when initialization fails after L.map() succeeds.
  // heritage-enhancements.js can then validate/rebuild a stale map and restore missing pins.
  if (mapContainer && !window.__heritageLeafletMap) {
    mapContainer.innerHTML = '<div class="map-loading" role="status">ম্যাপ শুরু করা যায়নি; বিকল্প মানচিত্র চালু করার চেষ্টা হচ্ছে…</div>';
  }
}
try { renderItinerary(); } catch (error) { console.error('Itinerary rendering failed:', error); }
try { renderReviews(); } catch (error) { console.error('Review rendering failed:', error); }
try { if (activePlaceId) renderPlaceDetail(selectedPlace()); } catch (error) { console.error('Place detail rendering failed:', error); }
loadPublishedCommunityPlaces().then(() => {
  try { renderPlaces(); } catch (error) { console.error('Place refresh failed:', error); }
  try { renderItinerary(); } catch (error) { console.error('Itinerary refresh failed:', error); }
  try { renderReviews(); } catch (error) { console.error('Review refresh failed:', error); }
  try { if (activePlaceId) renderPlaceDetail(selectedPlace()); } catch (error) { console.error('Place detail refresh failed:', error); }
}).catch(error => console.warn('Community content unavailable; base directory remains usable.', error));
